insert into public.students (
  school_id,legacy_id,admission_number,first_name,middle_name,last_name,preferred_name,
  gender,date_of_birth,admission_date,class_id,roll_number,category,nhis_no,ghana_card_no,
  previous_school,address_line,city,region,postal_code,nationality,second_nationality,
  country_of_birth,photo_url,medical_notes,dietary_requirements,allergies,special_needs,
  house_name,admission_type,concession_percent,media_consent,transport_required,
  transport_route,status,legacy_payload
)
select
  p.school_id,src.legacy_id,src.admission_number,src.first_name,src.middle_name,src.last_name,
  src.preferred_name,src.gender,src.date_of_birth::date,src.admission_date::date,c.id,
  src.roll_number,src.category,src.nhis_no,src.ghana_card_no,src.previous_school,
  src.address_line,src.city,src.region,src.postal_code,src.nationality,src.second_nationality,
  src.country_of_birth,src.photo_url,src.medical_notes,src.dietary_requirements,src.allergies,
  src.special_needs,src.house_name,src.admission_type,coalesce(src.concession_percent,0),
  src.media_consent,src.transport_required,src.transport_route,src.status::public.student_status,
  src.legacy_payload
from src
cross join params p
join public.classes c on c.school_id=p.school_id and c.legacy_id=src.class_legacy_id
on conflict (school_id,legacy_id) where legacy_id is not null do update set
  admission_number=excluded.admission_number,
  first_name=excluded.first_name,middle_name=excluded.middle_name,last_name=excluded.last_name,
  preferred_name=excluded.preferred_name,gender=excluded.gender,date_of_birth=excluded.date_of_birth,
  admission_date=excluded.admission_date,class_id=excluded.class_id,roll_number=excluded.roll_number,
  category=excluded.category,nhis_no=excluded.nhis_no,ghana_card_no=excluded.ghana_card_no,
  previous_school=excluded.previous_school,address_line=excluded.address_line,city=excluded.city,
  region=excluded.region,postal_code=excluded.postal_code,nationality=excluded.nationality,
  second_nationality=excluded.second_nationality,country_of_birth=excluded.country_of_birth,
  photo_url=excluded.photo_url,medical_notes=excluded.medical_notes,
  dietary_requirements=excluded.dietary_requirements,allergies=excluded.allergies,
  special_needs=excluded.special_needs,house_name=excluded.house_name,
  admission_type=excluded.admission_type,concession_percent=excluded.concession_percent,
  media_consent=excluded.media_consent,transport_required=excluded.transport_required,
  transport_route=excluded.transport_route,status=excluded.status,legacy_payload=excluded.legacy_payload;

commit;
